import{_ as o,o as e,c as a,a2 as l}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"M7 工具與沙箱","description":"","frontmatter":{},"headers":[],"relativePath":"build/m7-tools-sandbox.md","filePath":"build/m7-tools-sandbox.md","lastUpdated":null}'),r={name:"build/m7-tools-sandbox.md"};function i(d,t,n,s,c,p){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="m7-工具與沙箱" tabindex="-1">M7 工具與沙箱 <a class="header-anchor" href="#m7-工具與沙箱" aria-label="Permalink to &quot;M7 工具與沙箱&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ◇ 進階</li><li>狀態: 可閱讀 (M7.2 至 M7.5 僅有大綱)</li><li>資料基準日: 2026-10-26</li><li>待查證: MCP 授權規範細節未逐條驗證; ToolHive, gVisor 的設定未實機驗證</li></ul></div><p><strong>結論</strong>: 工具讓模型能讀寫系統, 也是風險最集中的地方. 所有工具都放在獨立的 VM 工具區, 經同一個工具閘道 (MCP gateway) 呼叫; 會執行程式碼的工具一律放進沙箱. 工具只有幾個時, 可以由 LiteLLM 兼任工具閘道.</p><p><strong>這一塊在圖上的位置</strong>: VM 工具區 (MCP 伺服器, Docker + gVisor) 與閘道區的 MCP gateway. <strong>前置模組</strong>: M5, M6. <strong>完成後的狀態</strong>: 介面與代理都能透過同一個工具閘道呼叫已審核的工具, 每次呼叫都留下紀錄.</p><h2 id="m7-1-mcp-伺服器的審核與沙箱化" tabindex="-1">M7.1 MCP 伺服器的審核與沙箱化 <a class="header-anchor" href="#m7-1-mcp-伺服器的審核與沙箱化" aria-label="Permalink to &quot;M7.1 MCP 伺服器的審核與沙箱化&quot;">​</a></h2><p>已公開的事件顯示風險真實存在:</p><table tabindex="0"><thead><tr><th>日期</th><th>事件</th><th>來源</th></tr></thead><tbody><tr><td>2025-04</td><td>Invariant Labs 公開工具投毒 (tool poisoning): 在工具描述中藏指令, 讓模型讀取 SSH 私鑰</td><td>pipelab.org, agentmelt.com 整理</td></tr><tr><td>2025-06</td><td>CVE-2025-49596, 官方 MCP Inspector 缺乏驗證, 可經惡意網頁執行程式碼 (CVSS 9.4)</td><td>The Hacker News, Vulnerable MCP Project</td></tr><tr><td>2025-07</td><td>CVE-2025-6514, mcp-remote 經惡意伺服器注入作業系統命令 (CVSS 9.6), 0.1.16 修補</td><td>JFrog, The Hacker News</td></tr><tr><td>2025-09</td><td>postmark-mcp npm 套件後門, 首例實際環境中的惡意 MCP 伺服器</td><td>pipelab.org</td></tr><tr><td>2026-06</td><td>Miasma 蠕蟲在 73 個 GitHub 儲存庫植入惡意 MCP 設定檔, IDE 開啟專案即自動執行</td><td>Cloud Security Alliance</td></tr></tbody></table><p>另有研究 &quot;MCP at First Glance&quot; (arXiv:2506.13538) 分析 1,899 個開源 MCP 伺服器, 摘要指出 7.2% 含一般漏洞, 5.5% 有 MCP 特有的工具投毒.</p><p>審核做法 (信心: 中高):</p><ol><li><strong>來源</strong>: 只用官方或知名組織維護的伺服器, 確認套件發行者與儲存庫一致.</li><li><strong>鎖定版本</strong>: 固定版本號與雜湊, 不用 <code>npx -y</code> 拉最新版; 工具描述變更時重新審核, 以防 rug pull.</li><li><strong>權限最小化</strong>: 檔案系統伺服器只開放單一資料夾; 資料庫伺服器使用唯讀帳號.</li><li><strong>沙箱化</strong>: stdio 伺服器放進容器 (無網路或限制對外連線, 非 root, 唯讀根檔案系統).</li><li><strong>不讓專案自動載入 MCP 設定</strong>: 關閉 IDE 的自動信任.</li><li><strong>MCP 閘道</strong>: 對初階讀者過度, 且 LiteLLM 的 MCP 路由本身就出過多個 CVE; 里程碑 3 才加入, 見 M7.2 節.</li></ol><h2 id="m7-2-架設工具閘道-mcp-gateway" tabindex="-1">M7.2 架設工具閘道 (MCP gateway) <a class="header-anchor" href="#m7-2-架設工具閘道-mcp-gateway" aria-label="Permalink to &quot;M7.2 架設工具閘道 (MCP gateway)&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>ToolHive 的部署方式 (容器), 工具白名單, 依角色授權, 稽核紀錄</li><li>規模小時改用 LiteLLM 的 MCP 功能兼任</li><li>第二次政策判定: 代理端判定後, 工具閘道再判定一次</li></ul><h2 id="m7-3-架設程式碼沙箱-docker-gvisor" tabindex="-1">M7.3 架設程式碼沙箱 (Docker + gVisor) <a class="header-anchor" href="#m7-3-架設程式碼沙箱-docker-gvisor" aria-label="Permalink to &quot;M7.3 架設程式碼沙箱 (Docker + gVisor)&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>在 VM 工具區安裝 gVisor 的 runsc, 以 <code>--runtime runsc</code> 執行沙箱容器</li><li>啟動參數: <code>--network none</code>, <code>--read-only</code>, 非 root, <code>--cap-drop ALL</code>, 記憶體, CPU 與行程數上限, 執行逾時</li><li>每次執行用新容器, 結束即刪除</li><li>以一支小型 MCP 伺服器接收程式碼, 啟動沙箱, 回傳結果</li></ul><h2 id="m7-4-讓-open-webui-使用同一組工具" tabindex="-1">M7.4 讓 Open WebUI 使用同一組工具 <a class="header-anchor" href="#m7-4-讓-open-webui-使用同一組工具" aria-label="Permalink to &quot;M7.4 讓 Open WebUI 使用同一組工具&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>Open WebUI 原生支援 MCP (Streamable HTTP), 在管理設定的外部工具加入工具閘道網址</li><li>關閉伺服器端的 Jupyter 程式碼執行引擎; 外掛 (Tools, Functions) 只限管理者匯入</li><li>若啟用 Open Terminal, 部署在 VM 工具區</li></ul><h2 id="m7-5-驗收測試" tabindex="-1">M7.5 驗收測試 <a class="header-anchor" href="#m7-5-驗收測試" aria-label="Permalink to &quot;M7.5 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>工具閘道拒絕白名單以外的工具呼叫, 並留下紀錄</li><li>沙箱內的程式無法連線外部網路, 無法寫入唯讀目錄</li><li>工具描述變更時, 審核流程能偵測到</li></ul>',22)])])}const M=o(r,[["render",i]]);export{u as __pageData,M as default};
